// n8n "Function" node
// Entrada esperada por item: { query: "<string JSON como el que enviaste>" }
// Salida por item: { JSON: "<string con el JSON interno>", nombre: "<nombre del archivo>" }

const out = [];

for (const item of items) {
  const q = item.json.query;
  if (!q) continue;

  // La propiedad `query` puede venir como string (lo más común) o ya como objeto/array
  const lista = typeof q === 'string' ? JSON.parse(q)
              : Array.isArray(q)       ? q
              : [q];

  for (const e of lista) {
    // Aseguramos que JSON sea string
    let contenido = e?.JSON;
    if (typeof contenido !== 'string') {
      try { contenido = JSON.stringify(contenido); } catch { contenido = String(contenido); }
    }

    out.push({
      json: {
        JSON: contenido,
        nombre: e?.nombre ?? ''
      }
    });
  }
}

return out;
